 public function validate(CommitteeElection $election,int $userId):array{$result=DB::transaction(function()use($election,$userId){$election=CommitteeElection::whereKey($election->id)->lockForUpdate()->firstOrFail();if(!in_array($election->status,[CommitteeElectionStatus::CLOSED,CommitteeElectionStatus::SCRUTINIZED,CommitteeElectionStatus::RESULTS_VALIDATED],true))throw ValidationException::withMessages(['status'=>'La elección debe estar cerrada para validar sus resultados.']);$summary=app(CommitteeElectionResultService::class)->calculate($election);$seats=$election->formationProcess->required_worker_principals+$election->formationProcess->required_worker_substitutes;if(count($summary['results'])<$seats)throw ValidationException::withMessages(['results'=>'No existen suficientes candidatos para cubrir principales y suplentes.']);if($seats>0&&isset($summary['results'][$seats])&&$summary['results'][$seats-1]['votes']===$summary['results'][$seats]['votes']){$votes=$summary['results'][$seats-1]['votes'];$ids=collect($summary['results'])->where('votes',$votes)->pluck('id')->all();$resolved=$election->ties()->where('status','resolved')->where('votes',$votes)->latest('resolved_at')->first();if(!$resolved||array_diff($ids,$resolved->candidate_ids)){$election->ties()->where('status','pending')->delete();$election->ties()->create(['candidate_ids'=>$ids,'votes'=>$votes,'affected_positions'=>1,'status'=>'pending']);$election->update(['status'=>'scrutinized','scrutinized_at'=>now(),'result_integrity_hash'=>$summary['digest'],'updated_by'=>$userId]);$this->audit($election,'tie_detected',$userId,['candidate_ids'=>$ids,'votes'=>$votes]);return['tie'=>true];}$priority=array_flip($resolved->candidate_ids);usort($summary['results'],fn($a,$b)=>$b['votes']<=>$a['votes']?:($priority[$a['id']]??999)<=>($priority[$b['id']]??999));}$election->update(['status'=>'ready_for_formation','scrutinized_at'=>$election->scrutinized_at??now(),'results_validated_at'=>now(),'result_integrity_hash'=>$summary['digest'],'updated_by'=>$userId]);$this->audit($election,'results_validated',$userId,['integrity_hash'=>$summary['digest'],'seats'=>$seats]);return['tie'=>false,'summary'=>$summary];});if($result['tie'])throw ValidationException::withMessages(['tie'=>'Existe un empate que afecta puestos. Registre su resolución y vuelva a validar.']);return$result['summary'];}
 public function resolveTie(CommitteeElectionTie $tie,int $preferredCandidateId,string $method,string $observations,int $userId):void{abort_unless($tie->status==='pending',422,'El empate ya fue resuelto.');$ids=$tie->candidate_ids;abort_unless(in_array($preferredCandidateId,$ids,true),422,'El candidato no pertenece al empate.');$ordered=array_values(array_unique(array_merge([$preferredCandidateId],$ids)));$tie->update(['candidate_ids'=>$ordered,'status'=>'resolved','resolution_method'=>$method,'observations'=>$observations,'resolved_by'=>$userId,'resolved_at'=>now()]);$this->audit($tie->election,'tie_resolved',$userId,['tie_id'=>$tie->id,'priority'=>$ordered,'method'=>$method]);}
 private function audit(CommitteeElection $election,string $event,int $userId,array $metadata=[]):void{$election->audits()->create(['event'=>$event,'user_id'=>$userId,'metadata'=>$metadata,'created_at'=>now()]);}
